<script setup>import AppShell from '../components/AppShell.vue';import StatusPill from '../components/StatusPill.vue';import {equipment,inspections,workOrders} from '../api/mock';const props=defineProps({mode:String,module:String});const titles={tasks:['工序任务','按工作中心接收与执行生产任务'],material:['物料追溯','记录领料、投料、退料与批次流转'],quality:['质量管理','执行首检、巡检、不良处置与完工检验'],andon:['异常呼叫','发起并跟踪设备、质量和物料异常'],schedule:['计划排程','平衡订单交期、产能与物料齐套情况'],process:['工艺路线','维护产品工序、作业指导与控制参数'],equipment:['设备管理','掌握设备状态、点检、保养与综合效率'],report:['生产分析','分析达成率、效率、质量与停机损失']};const meta=titles[props.module]||['制造协同','生产执行与过程跟踪'];const data=props.module==='equipment'?equipment:props.module==='quality'?inspections:workOrders</script>
<template><AppShell :mode="mode"><div class="page-head"><div><span class="breadcrumb">{{mode==='shopfloor'?'车间执行':'生产管理'}} / {{meta[0]}}</span><h1>{{meta[0]}}</h1><p>{{meta[1]}}</p></div><button class="primary">+ 新建记录</button></div><section class="panel list-panel"><div class="toolbar"><div class="tabs"><button class="active">全部 <em>{{data.length}}</em></button><button>待处理</button><button>已完成</button></div><div class="filters"><input placeholder="输入编号、设备或产品"/><select><option>全部状态</option></select><button class="secondary">查询</button></div></div><table><thead><tr><th>业务编号</th><th>业务内容</th><th>所属单元</th><th>关键数据</th><th>状态</th><th></th></tr></thead><tbody><tr v-for="(item,i) in data" :key="i"><td><b>{{item.no||item.code}}</b></td><td>{{item.product||item.name}}</td><td>{{item.center||item.type||item.workshop}}</td><td>{{item.plan?item.done+' / '+item.plan:item.oee?item.oee+'% OEE':item.sample+' 件抽样'}}</td><td><StatusPill :text="item.status||item.result"/></td><td><button class="link-button">查看详情</button></td></tr></tbody></table></section></AppShell></template>
